from math import pi, cos, sqrt, sin, acos, asindef distance(x1, y1, x2, y2):    return sqrt((x2 - x1) ** 2 + (y2 - y1) ** 2)def solving_quadratic_equation(a, b, c):    return (-b + sqrt(b ** 2 - 4 * a * c)) / (2 * a), (-b - sqrt(b ** 2 - 4 * a * c)) / (2 * a)# B = int(input())# S = int(input())# a = int(input())# b = int(input())# H = int(input())B = 500S = 50_000a = 30b = 60Vr = 1_500Vt = 2400c = b - aSpzu = sqrt(B ** 2 + S ** 2 - 2 * B * S * cos(c * pi / 180))print(f"{Spzu:.2f}")if S * S < B * B + Spzu * Spzu:    print("ПЗУ острый")elif S * S > B * B + Spzu * Spzu:    print("ПЗУ тупой")if Spzu ** 2 < B * B + S * S:    print("СОУ острый")elif Spzu ** 2 > B * B + S * S:    print("СОУ тупой")# ЗА ПЗУ цель летитy0_pzu = cos(c * pi / 180) * S - B  # возможно здесь только модульx0_pzu = 0x0_target = S * sin(c * pi / 180)y0_target = 0dist = distance(x0_pzu, y0_pzu, x0_target, y0_target)print(f"Исходное расстояние: {dist}")a = (Vr ** 2 - Vt ** 2)b = 2 * x0_target * Vtc = x0_target ** 2 + y0_target ** 2t_min, t_max = solving_quadratic_equation(a, b, c)print(f"Минимальное время: {t_min}")print(f"Максимальное время: {t_max}")beta = asin(-y0_pzu/(Vr*t_max))beta = beta * 180 / piprint(f"Угол: {beta}")# alfa = acos((x0_target-Vt*t_max)/(Vr*t_max))# alfa = alfa * 180 / pi# print(f"Угол: {alfa}")print(distance(x0_pzu,y0_pzu,x0_target-Vt*t_max,0))